def solve(stream, registers):
    # Initialize the register to 0
    registers.set(0, 0)

    # Process exactly 4 bits from the stream
    for _ in range(4):
        bit = stream.next_bit()
        # The current count is retrieved from the only available register
        count = registers.get(0)
        # Update the register if the bit is 1
        if bit == 1:
            registers.set(0, count + 1)

    # Return the final count stored in the register
    return registers.get(0)

def solve(stream, registers):
    # Initialize registers to 0
    registers.set(0, 0)
    registers.set(1, 0)

    # Process 4 bits
    for _ in range(4):
        bit = stream.next_bit()
        if bit == 1:
            val0 = registers.get(0)
            if val0 < 3:
                registers.set(0, val0 + 1)
            else:
                # Current count is 3, this 1 makes it 4
                # Reset register 0 to 0 and increment register 1 (the '4s' place)
                registers.set(0, 0)
                registers.set(1, registers.get(1) + 1)

    # Total count = (register 1 * 4) + register 0
    return (registers.get(1) * 4) + registers.get(0)

