from functools import lru_cache

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def solve(n):
        if n <= 0:
            return 0
        s = str(n)
        length = len(s)

        @lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            if idx == length:
                # A number is beautiful if it has started and counts of even/odd are equal (diff == 0)
                # and it is divisible by k (rem == 0)
                return 1 if (is_started and diff == 0 and rem == 0) else 0

            res = 0
            # Handle leading zeros: if the number hasn't started yet, we can skip this position
            if not is_started:
                res += dp(idx + 1, 0, 0, True, False)

            # Determine the range of digits we can place at this position
            limit = int(s[idx]) if not is_less else 9
            # If the number hasn't started, the first digit cannot be 0
            start = 1 if not is_started else 0

            for digit in range(start, limit + 1):
                new_is_less = is_less or (digit < limit)
                # Even digits increment diff, odd digits decrement diff
                new_diff = diff + (1 if digit % 2 == 0 else -1)
                new_rem = (rem * 10 + digit) % k
                res += dp(idx + 1, new_diff, new_rem, new_is_less, True)

            return res

        return dp(0, 0, 0, False, False)

    return solve(high) - solve(low - 1)

from typing import Optional, List

def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    # The leftmost character of row i must be r[i]: grid[i][0] = r[i]
    # The topmost character of col j must be c[j]: grid[0][j] = c[j]
    # This implies grid[0][0] must be both r[0] and c[0].
    if r[0] != c[0]:
        return None

    grid = [['.' for _ in range(n)] for _ in range(n)]

    def is_valid(row, col, char):
        if char == '.':
            return True
        # Check row constraint: char cannot appear more than once
        for j in range(n):
            if grid[row][j] == char:
                return False
        # Check column constraint: char cannot appear more than once
        for i in range(n):
            if grid[i][col] == char:
                return False
        return True

    def solve(row, col):
        if row == n:
            # Final validation: each row and col must have exactly one 'A', 'B', 'C'
            for i in range(n):
                row_set = {grid[i][j] for j in range(n) if grid[i][j] != '.'}
                if row_set != {'A', 'B', 'C'}:
                    return False
            for j in range(n):
                col_set = {grid[i][j] for i in range(n) if grid[i][j] != '.'}
                if col_set != {'A', 'B', 'C'}:
                    return False
            return True

        next_row, next_col = (row, col + 1) if col < n - 1 else (row + 1, 0)

        # Fixed cell: leftmost column
        if col == 0:
            char = r[row]
            # Since grid[0][0] is already set, check others against column constraint
            if row > 0:
                for i in range(row):
                    if grid[i][0] == char:
                        return False
            grid[row][0] = char
            if solve(next_row, next_col):
                return True
            grid[row][0] = '.'
            return False

        # Fixed cell: topmost row
        if row == 0:
            char = c[col]
            # Check against row constraint (grid[0][0] already exists)
            for j in range(col):
                if grid[0][j] == char:
                    return False
            grid[0][col] = char
            if solve(next_row, next_col):
                return True
            grid[0][col] = '.'
            return False

        # Regular cell: Try 'A', 'B', 'C', or '.'
        for char in ['A', 'B', 'C', '.']:
            if char != '.':
                if not is_valid(row, col, char):
                    continue
            grid[row][col] = char
            if solve(next_row, next_col):
                return True
            grid[row][col] = '.'

        return False

    # Initialize the fixed start point to avoid redundant logic inside solve
    grid[0][0] = r[0]
    if solve(0, 1):
        return ["".join(row) for row in grid]
    return None

from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside
    """
    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell (top-to-bottom, left-to-right)
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1: # All cells covered
            return True

        # Try placing each unused tile at the first available empty cell
        for i in range(n):
            if not used[i]:
                # Try both orientations of the tile
                # Use a set to avoid redundant checks if the tile is square
                orientations = {(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])}
                for th, tw in orientations:
                    # Check if tile fits within grid boundaries
                    if r + th <= h and c + tw <= w:
                        # Check if all cells for this tile placement are empty
                        possible = True
                        for dr in range(th):
                            for dc in range(tw):
                                if grid[r + dr][c + dc]:
                                    possible = False
                                    break
                            if not possible: break

                        if possible:
                            # Place tile
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = True
                            used[i] = True

                            if solve():
                                return True

                            # Backtrack
                            used[i] = False
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = False
        return False

    # Pre-check: Total area of available tiles must be at least the grid area
    if sum(a * b for a, b in tiles) < h * w:
        return False

    return solve()

def count_beautiful_numbers(l: int, r: int) -> int:
    def solve(n):
        if n <= 0:
            return 0
        s_n = str(n)
        length = len(s_n)

        def count_no_zero_with_sum(S, limit_str):
            L = len(limit_str)
            memo = {}
            def dp(idx, curr_sum, curr_prod_mod, is_less):
                state = (idx, curr_sum, curr_prod_mod, is_less)
                if state in memo: return memo[state]
                if idx == L:
                    return 1 if curr_sum == S and curr_prod_mod == 0 else 0

                res = 0
                limit = int(limit_str[idx]) if not is_less else 9
                for d in range(1, limit + 1):
                    if curr_sum + d <= S:
                        res += dp(idx + 1, curr_sum + d, (curr_prod_mod * d) % S, is_less or (d < limit))
                memo[state] = res
                return res
            return dp(0, 0, 1, False)

        def count_no_zero_fixed_len(L, S):
            memo = {}
            def dp(idx, curr_sum, curr_prod_mod):
                state = (idx, curr_sum, curr_prod_mod)
                if state in memo: return memo[state]
                if idx == L:
                    return 1 if curr_sum == S and curr_prod_mod == 0 else 0
                res = 0
                for d in range(1, 10):
                    if curr_sum + d <= S:
                        res += dp(idx + 1, curr_sum + d, (curr_prod_mod * d) % S)
                memo[state] = res
                return res
            return dp(0, 0, 1)

        def count_no_zero_total(n_str):
            L_max = len(n_str)
            total = 0
            # Fixed lengths shorter than n_str
            for L in range(1, L_max):
                for S in range(L, 9 * L + 1):
                    total += count_no_zero_fixed_len(L, S)
            # Length exactly L_max
            for S in range(L_max, 9 * L_max + 1):
                total += count_no_zero_with_sum(S, n_str)
            return total

        def count_with_zero(n_str):
            n_val = int(n_str)
            l_s = len(n_str)
            # Count numbers in [1, n] with no zero
            no_zero_count = 0
            # Lengths 1 to L_max - 1
            for i in range(1, l_s):
                no_zero_count += 9**i
            # Length L_max
            for i in range(l_s):
                digit = int(n_str[i])
                for d in range(1, digit):
                    no_zero_count += 9**(l_s - 1 - i)
                if digit == 0: break
                if i == l_s - 1: no_zero_count += 1
            return n_val - no_zero_count

        return count_with_zero(s_n) + count_no_zero_total(s_n)

    return solve(r) - solve(l - 1)

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_up_to(n_str, min_s, max_s):
        if not n_str:
            return 0

        memo = {}

        def dp(idx, current_sum, is_less):
            state = (idx, current_sum, is_less)
            if state in memo:
                return memo[state]

            if idx == len(n_str):
                return 1 if min_s <= current_sum <= max_s else 0

            if current_sum > max_s:
                return 0

            limit = int(n_str[idx]) if not is_less else 9
            res = 0

            for digit in range(limit + 1):
                next_is_less = is_less or (digit < limit)
                res = (res + dp(idx + 1, current_sum + digit, next_is_less)) % MOD

            memo[state] = res
            return res

        return dp(0, 0, False)

    def get_digit_sum(s):
        return sum(int(d) for d in s)

    # Result is count(num2) - count(num1) + (1 if num1 is good else 0)
    ans_num2 = count_up_to(num2, min_sum, max_sum)
    ans_num1 = count_up_to(num1, min_sum, max_sum)

    is_num1_good = 1 if min_sum <= get_digit_sum(num1) <= max_sum else 0

    return (ans_num2 - ans_num1 + is_num1_good) % MOD

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j] is the min changes to make s[i:j+1] a semi-palindrome
    cost = [[float('inf')] * n for _ in range(n)]

    def get_semi_palindrome_cost(sub):
        m = len(sub)
        if m < 2:
            return float('inf')

        min_total_cost = float('inf')
        # Find all divisors d such that 1 <= d < m
        # The condition is: there exists a positive integer d such that 1 <= d < len and len % d == 0
        for d in range(1, m):
            if m % d == 0:
                current_cost = 0
                # For each group based on index % d
                for start in range(d):
                    # The group is sub[start], sub[start+d], ..., sub[start + (m//d - 1)*d]
                    # This group must be a palindrome
                    # indices in sub: start, start+d, start+2d, ..., start + (m//d - 1)*d
                    # let length of group be L = m // d
                    L = m // d
                    for i in range(L // 2):
                        if sub[start + i * d] != sub[start + (L - 1 - i) * d]:
                            current_cost += 1
                if current_cost < min_total_cost:
                    min_total_cost = current_cost
        return min_total_cost

    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = get_semi_palindrome_cost(s[i : j + 1])

    # dp[i][j] is the min cost to partition s[0:j] into i semi-palindromes
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(1, k + 1):
        # A partition into i semi-palindromes requires at least 2*i characters
        for j in range(2 * i, n + 1):
            # The last substring is s[p:j], its length (j-p) must be >= 2
            # Also, the prefix s[0:p] must be partitionable into i-1 semi-palindromes (p >= 2*(i-1))
            for p in range(2 * (i - 1), j - 1):
                if dp[i - 1][p] != float('inf') and cost[p][j - 1] != float('inf'):
                    if dp[i - 1][p] + cost[p][j - 1] < dp[i][j]:
                        dp[i][j] = dp[i - 1][p] + cost[p][j - 1]

    return int(dp[k][n])

